# Code generated by Claude
"""
Tests of the bench rectangle stance selection (src/bench_rectangle.py, src/stance_select.py) without the simulator: made-up rectangles on the config world (the beaker at (1.00, 0.66), the hotplate at (0.80, 0.66)).

    python experiments/stance_select_test.py

1. The largest rectangle of a made-up reachable area, and the shrink by the margin.
2. The parking pose centres the targets' box in the rectangle (heading -90 degrees, the bench on the +y side) and `fits` agrees.
3. Runs: with a wide rectangle both objects are one run and the second navigation step is NULL; with a narrow one they are two runs; the cap of 4 steps.
4. The full check as the safety net: a failing first spot gives the shifted spots in order (+5 cm along, -5 cm along, +3 cm toward, -3 cm away: at most 4), and all failing stops with the reason.
5. The pick's return to the zombie pose (end_at_zombie) only when the next navigation step moves.
6. The default: BENCH_RECT_CFG["mode"] is "task_cfg" and a missing rectangle is an error, not a guess.
"""

import copy
import math
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.bench_rectangle import fits, largest_rectangle, parking_pose  # noqa: E402
from src.mpvi_plan import BEAKER_ON_HOTPLATE_LABELS  # noqa: E402
from src.mpvi_postprocess import make_stored_labeler, postprocess  # noqa: E402
from src.stance_select import plan_runs, select_bench_stance  # noqa: E402
from src.task_config import BENCH_RECT_CFG, TASK_CFG  # noqa: E402
from src.world_model import StaticTaskSource, WorldModel  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


PLAN4 = {"task_name": "Put the beaker on the hotplate", "segments": [
    {"type": "navigation", "description": "Go to the beaker", "completion_criteria": "At the beaker", "target": "the beaker"},
    {"type": "manipulation", "description": "Pick up the beaker", "completion_criteria": "The beaker is held", "target": None},
    {"type": "navigation", "description": "Go to the hotplate", "completion_criteria": "At the hotplate", "target": "the hotplate"},
    {"type": "manipulation", "description": "Place the beaker on the hotplate", "completion_criteria": "The beaker is on the hotplate and the gripper is open", "target": None}]}
LABELS4 = {"labels": [{"index": 1, "primitive": "pick", "objects": [{"phrase": "the beaker", "role": "manipulated"}]},
                      {"index": 3, "primitive": "place", "objects": [{"phrase": "the beaker", "role": "manipulated"}, {"phrase": "the hotplate", "role": "destination"}]}]}
WIDE = {"forward_near": 0.30, "forward_far": 0.70, "right": -0.35, "left": 0.35}
NARROW = {"forward_near": 0.30, "forward_far": 0.70, "right": -0.05, "left": 0.05}


class FakeCheck:
    def __init__(self, ok_after):
        self.calls, self.ok_after = [], ok_after

    def check(self, stance, points):
        self.calls.append(stance)
        ok = len(self.calls) > self.ok_after
        return {"ok": ok, "reason": "" if ok else "fake: home_clearance", "seconds": {"x": 0.1}}


def main():
    print("1. the largest rectangle and the shrink")
    m = np.zeros((20, 30), bool)
    m[3:15, 5:25] = True
    m[8, 10] = False
    r = largest_rectangle(m)
    area = lambda r: (r[1] - r[0] + 1) * (r[3] - r[2] + 1)
    check("the rectangle found is all True", r is not None and bool(m[r[0]:r[1] + 1, r[2]:r[3] + 1].all()), f"{r}")
    check("it is the largest: 12 rows x 14 columns = 168 cells (the hole at row 8, column 10 costs the wider side)", area(r) == 168, f"area {area(r)}")
    check("an empty area has no rectangle", largest_rectangle(np.zeros((4, 4), bool)) is None)

    print("\n2. the parking pose")
    yaw = math.radians(-90.0)
    tg = np.array([[1.00, 0.66], [0.80, 0.66]])
    pose, ok = parking_pose(WIDE, tg, yaw)
    check("the targets' box is centred in the rectangle: forward 0.50, left 0.0 from the base", ok and fits(WIDE, pose, tg), f"pose {np.round(pose, 3).tolist()}")
    c, s = math.cos(yaw), math.sin(yaw)
    mid = np.array([0.9, 0.66])
    f, l = c * (mid[0] - pose[0]) + s * (mid[1] - pose[1]), -s * (mid[0] - pose[0]) + c * (mid[1] - pose[1])
    check("the box centre is at the rectangle's centre in the base frame", abs(f - 0.5) < 1e-9 and abs(l - 0.0) < 1e-9, f"forward {f:.3f} left {l:.3f}")
    pose2, ok2 = parking_pose(NARROW, tg, yaw)
    check("a narrow rectangle does not fit the two targets 20 cm apart (the targets' left-right extent 0.20 > 0.10)", not ok2)
    check("one target fits", parking_pose(NARROW, tg[:1], yaw)[1])

    print("\n3. runs and the null navigation step")
    world = WorldModel([StaticTaskSource()])
    world.refresh(0.0)
    tagged = postprocess(PLAN4, make_stored_labeler(LABELS4), False)
    runs = plan_runs(tagged, world, yaw, WIDE)
    check("wide rectangle: one run, the second navigation step is null", len(runs) == 1 and runs[0]["nav"] == [0, 2] and runs[0]["steps"] == [1, 3] and runs[0]["fits"], f"{[(r['nav'], r['steps']) for r in runs]}")
    runs = plan_runs(tagged, world, yaw, NARROW)
    check("narrow rectangle: two runs, each navigation step moves", len(runs) == 2 and runs[0]["nav"] == [0] and runs[1]["nav"] == [2], f"{[(r['nav'], r['steps']) for r in runs]}")
    big = copy.deepcopy(PLAN4)
    for _ in range(2):
        big["segments"] += [PLAN4["segments"][2], PLAN4["segments"][3]]
    place = lambda i: {"index": i, "primitive": "place", "objects": [{"phrase": "the beaker", "role": "manipulated"}, {"phrase": "the hotplate", "role": "destination"}]}
    labels = {"labels": LABELS4["labels"] + [place(5), place(7)]}
    runs = plan_runs(postprocess(big, make_stored_labeler(labels), False), world, yaw, WIDE)
    check("the cap: 4 manipulation steps in one run are allowed (R7)", [len(r["steps"]) for r in runs] == [4] and runs[0]["nav"] == [0, 2, 4, 6], f"{[(r['nav'], r['steps']) for r in runs]}")
    big["segments"] += [PLAN4["segments"][2], PLAN4["segments"][3]]
    runs = plan_runs(postprocess(big, make_stored_labeler({"labels": labels["labels"] + [place(9)]}), False), world, yaw, WIDE)
    check("the 5th manipulation step starts a new run (and its navigation step moves)", [len(r["steps"]) for r in runs] == [4, 1] and runs[1]["nav"] == [8], f"{[(r['nav'], r['steps']) for r in runs]}")

    print("\n4. the full check as the safety net")
    cfg = {**BENCH_RECT_CFG, "rectangle": WIDE}
    fc = FakeCheck(0)
    sel = select_bench_stance(tagged, world, TASK_CFG, cfg, full_check=fc, points=[], say=lambda *a: None)
    check("the first spot passes: no shift, one check", sel["ok"] and len(fc.calls) == 1 and sel["report"]["candidates"][0]["shift"] == (0.0, 0.0), f"{sel['report']['chosen']}")
    check("the chosen spot is in the config of the staging (xy, heading kept)", sel["task_cfg"]["staging_xy"] == tuple(sel["report"]["chosen"]["xy"]) and sel["task_cfg"]["staging_yaw"] == TASK_CFG["staging_yaw"] and sel["task_cfg"]["pedestal_q"] == TASK_CFG["pedestal_q"])
    check("the second navigation step is reported null", sel["report"]["null_nav"] == [2])
    fc = FakeCheck(2)
    sel = select_bench_stance(tagged, world, TASK_CFG, cfg, full_check=fc, points=[], say=lambda *a: None)
    shifts = [c["shift"] for c in sel["report"]["candidates"]]
    check("two failures: the first spot, +5 cm and -5 cm along the bench are tried, the third is chosen", sel["ok"] and shifts == [(0.0, 0.0), (0.0, 0.05), (0.0, -0.05)], f"{shifts}")
    fc = FakeCheck(3)
    sel = select_bench_stance(tagged, world, TASK_CFG, cfg, full_check=fc, points=[], say=lambda *a: None)
    check("three failures: the fourth spot is 3 cm toward the bench (the forward direction of the base)", sel["ok"] and [c["shift"] for c in sel["report"]["candidates"]][-1] == (0.03, 0.0)
          and abs(np.hypot(*(np.array(sel["report"]["candidates"][3]["xy"]) - np.array(sel["report"]["candidates"][0]["xy"]))) - 0.03) < 1e-9, f"{[c['shift'] for c in sel['report']['candidates']]}")
    fc = FakeCheck(99)
    sel = select_bench_stance(tagged, world, TASK_CFG, cfg, full_check=fc, points=[], say=lambda *a: None)
    check("everything fails: the first spot and four shifted spots, then stop and report (5 checks, ok False, the original config)", not sel["ok"] and len(fc.calls) == 5 and sel["task_cfg"] is TASK_CFG and any("stop and report" in n for n in sel["report"]["notes"]), f"{len(fc.calls)} checks")
    sel = select_bench_stance(tagged, world, TASK_CFG, {**cfg, "rectangle": NARROW}, full_check=None, say=lambda *a: None)
    check("a narrow rectangle: the first run (the beaker alone) is parked, the second run (the place step: beaker and hotplate 20 cm apart) is reported as not fitting",
          sel["ok"] and sel["report"]["runs"][0]["fits"] and not sel["report"]["runs"][1]["fits"], f"{[r['fits'] for r in sel['report']['runs']]}")

    print("\n5. the pick returns to the zombie pose unless the next step is null")
    sel_wide = select_bench_stance(tagged, world, TASK_CFG, cfg, full_check=None, say=lambda *a: None)
    check("null second navigation: the pick does not go to the zombie pose", not sel_wide["plan"]["segments"][1].get("end_at_zombie"))
    # two parking spots needed: the first run only covers the beaker (a rectangle that fits one object); the pick is followed by a navigation step that moves
    sel_two = select_bench_stance(tagged, world, TASK_CFG, {**cfg, "rectangle": {"forward_near": 0.30, "forward_far": 0.70, "right": -0.08, "left": 0.08}}, full_check=None, say=lambda *a: None)
    check("a moving second navigation step: the pick ends at the zombie pose, the place does not", sel_two["plan"]["segments"][1].get("end_at_zombie") is True and not sel_two["plan"]["segments"][3].get("end_at_zombie"), f"{[s.get('end_at_zombie') for s in sel_two['plan']['segments']]}")
    check("the second stance is reported as not supported by the scripted staging", any("second stance" in n for n in sel_two["report"]["notes"]))

    print("\n6. the defaults")
    check("BENCH_RECT_CFG['mode'] is 'task_cfg' (today's stance)", BENCH_RECT_CFG["mode"] == "task_cfg")
    try:
        select_bench_stance(tagged, world, TASK_CFG, {**BENCH_RECT_CFG, "rectangle": None}, say=lambda *a: None)
        check("an unmeasured rectangle is an error", False)
    except ValueError as e:
        check("an unmeasured rectangle is an error, not a guess", "not measured" in str(e))
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
